CREATE TABLE account_tokens (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, token_hash CHAR(64) NOT NULL UNIQUE, purpose VARCHAR(20) NOT NULL, staff_identity_id BIGINT UNSIGNED NULL, user_id BIGINT UNSIGNED NULL, request_id BIGINT UNSIGNED NULL, email VARCHAR(190) NOT NULL, expires_at DATETIME NOT NULL, used_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(staff_identity_id) REFERENCES staff_identities(id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(request_id) REFERENCES registration_requests(id), INDEX(expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
